namespace gui_forms {

// PropertyGrid's property capabilities (property-capabilities study, sections
// 2, 14 and 15). Generated by tools/property_codemod.py from
// tools/property_families/property_grid.json: edit the config, not this file.
//
// Each is a standard-layout struct whose only member is its property's
// cell, taken by the declaring class as a base. A write
// `(*control).x = value;` runs `assign`: the declaring class's
// prepare_write hook (require_mutable first, then the value's checks and,
// where C# lets a subclass rewrite the value, the protected virtual coerce
// hook), the compare and store, then the written hook (the touch, side
// effects and the change event, through the protected virtual
// on_<property>_changed() where Windows Forms has OnXChanged). A read is
// `(*control).x.read()`.

// How the rows are ordered (PropertySort): grouped by category (the default) or alphabetical; a view onto the grid's projection. A change rebuilds the rows.
template <typename Declaring>
struct PropertyGridPropertySortCapability {
    PropertyView<PropertySort, PropertyGridPropertySortCapability<Declaring>> property_sort;

    static void assign(PropertyGridPropertySortCapability& capability, PropertySort incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.write_view(std::as_const(capability.property_sort), std::move(incoming));
    }

    static PropertySort read(const PropertyGridPropertySortCapability& capability) {
        const Declaring& control = static_cast<const Declaring&>(capability);
        PropertySort current = control.read_view(capability.property_sort);
        return current;
    }
};

// The value converters the grid's editors use; a view onto the projection. Never null (std::invalid_argument); a change rebuilds the rows.
template <typename Declaring>
struct PropertyGridConverterRegistryCapability {
    PropertyView<std::shared_ptr<PropertyValueConverterRegistry>, PropertyGridConverterRegistryCapability<Declaring>> converter_registry;

    static void assign(PropertyGridConverterRegistryCapability& capability, std::shared_ptr<PropertyValueConverterRegistry> incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.write_view(std::as_const(capability.converter_registry), std::move(incoming));
    }

    static std::shared_ptr<PropertyValueConverterRegistry> read(const PropertyGridConverterRegistryCapability& capability) {
        const Declaring& control = static_cast<const Declaring&>(capability);
        std::shared_ptr<PropertyValueConverterRegistry> current = control.read_view(capability.converter_registry);
        return current;
    }
};

// The editors the grid installs per property type; a view onto the projection. Never null (std::invalid_argument); a change rebuilds the rows.
template <typename Declaring>
struct PropertyGridEditorRegistryCapability {
    PropertyView<std::shared_ptr<PropertyEditorRegistry>, PropertyGridEditorRegistryCapability<Declaring>> editor_registry;

    static void assign(PropertyGridEditorRegistryCapability& capability, std::shared_ptr<PropertyEditorRegistry> incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.write_view(std::as_const(capability.editor_registry), std::move(incoming));
    }

    static std::shared_ptr<PropertyEditorRegistry> read(const PropertyGridEditorRegistryCapability& capability) {
        const Declaring& control = static_cast<const Declaring&>(capability);
        std::shared_ptr<PropertyEditorRegistry> current = control.read_view(capability.editor_registry);
        return current;
    }
};

// PropertySort as a property value; defined beside PropertyGrid's table.
template <>
struct PropertyValueTraits<PropertySort> {
    static PropertyType type();
    static BindingValue to_binding(PropertySort value);
    static PropertySort from_binding(const BindingValue& value);
};

// Every PropertyGrid capability, in the order the declaring class takes them.
template <typename Declaring>
struct PropertyGridCapabilities : public PropertyGridPropertySortCapability<Declaring>,
                                  public PropertyGridConverterRegistryCapability<Declaring>,
                                  public PropertyGridEditorRegistryCapability<Declaring> {};

} // namespace gui_forms
